import { execFileSync } from 'child_process';
import { subprocessEnvironment } from './subprocessEnvironment';
import * as fs from 'fs';

export function cloneOrCopyDirSync(source: string, destination: string): void {
  if (process.platform === 'darwin') {
    try {
      execFileSync('/bin/cp', ['-cR', source, destination], {
        stdio: 'ignore',
        env: subprocessEnvironment('verifier'),
      });
      return;
    } catch {
      fs.rmSync(destination, { recursive: true, force: true });
    }
  }
  fs.cpSync(source, destination, {
    recursive: true,
    dereference: false,
    verbatimSymlinks: true,
    mode: fs.constants.COPYFILE_FICLONE,
  });
}
